mapper.select:
/* 품종명 조회 */
SELECT VRTY_NM
  FROM VRTY
 WHERE VRTY_SN = #{vrtySn}

/* 사용 중인 품종 존재 여부(반려동물 종 일치) */
SELECT EXISTS (
       SELECT 1
         FROM VRTY
        WHERE VRTY_SN = #{vrtySn}
          AND PET_SE_CD = #{petSeCd}
          AND USE_YN = 'Y'
       )

/* 주양육 반려동물 수 조회 */
SELECT COUNT(*)
  FROM BRUP_REL R
  JOIN PET P
    ON P.PET_SN = R.PET_SN
   AND P.DEL_YN = 'N'
 WHERE R.MBR_SN = #{mbrSn}
   AND R.BRUP_ROLE_CD = #{primaryRoleCd}
   AND R.USE_YN = 'Y'

mapper.insert:
/* 반려동물 등록 */
INSERT INTO PET
     ( VRTY_SN
     , PET_SE_CD
     , PET_GNDR_CD
     , COLR_CD
     , PET_NM
     , VRTY_DRCT_INPT_NM
     , COLR_DRCT_INPT_NM
     , CHIP_NO
     , CHRC_CN
     , ALGY_CN
     , DSS_CN
     , PET_BRDT
     , PET_BDWG
     , GOAL_BDWG
     , MIN_BDWG
     , MAX_BDWG
     , NUTR_YN
     , RGTR_ID
     , MDFR_ID
     )
VALUES
     ( #{vrtySn}
     , #{petSeCd}
     , #{petGndrCd}
     , #{colrCd}
     , #{petNm}
     , #{vrtyDrctInptNm}
     , #{colrDrctInptNm}
     , #{chipNo}
     , #{chrcCn}
     , #{algyCn}
     , #{dssCn}
     , #{petBrdt}
     , #{petBdwg}
     , #{goalBdwg}
     , #{minBdwg}
     , #{maxBdwg}
     , #{nutrYn}
     , #{rgtrId}
     , #{mdfrId}
     )

/* 양육 관계 등록 */
INSERT INTO BRUP_REL
     ( PET_SN
     , MBR_SN
     , BRUP_ROLE_CD
     , RPRS_PET_YN
     , MDFR_ID
     )
VALUES
     ( #{petSn}
     , #{mbrSn}
     , #{brupRoleCd}
     , #{rprsPetYn}
     , #{mdfrId}
     )

mapper.update:
/* 반려동물 수정 */
UPDATE PET
   SET VRTY_SN           = #{pet.vrtySn}
     , PET_SE_CD         = #{pet.petSeCd}
     , PET_GNDR_CD       = #{pet.petGndrCd}
     , COLR_CD           = #{pet.colrCd}
     , PET_NM            = #{pet.petNm}
     , VRTY_DRCT_INPT_NM = #{pet.vrtyDrctInptNm}
     , COLR_DRCT_INPT_NM = #{pet.colrDrctInptNm}
     , CHIP_NO           = #{pet.chipNo}
     , CHRC_CN           = #{pet.chrcCn}
     , ALGY_CN           = #{pet.algyCn}
     , DSS_CN            = #{pet.dssCn}
     , PET_BRDT          = #{pet.petBrdt}
     , PET_BDWG          = #{pet.petBdwg}
     , GOAL_BDWG         = #{pet.goalBdwg}
     , MIN_BDWG          = #{pet.minBdwg}
     , MAX_BDWG          = #{pet.maxBdwg}
     , NUTR_YN           = #{pet.nutrYn}
     , MDFR_ID           = #{actorId}
     , MDFCN_DT          = NOW()
 WHERE PET_SN = #{pet.petSn}
   AND DEL_YN = 'N'

/* 대표 반려동물 해제 */
UPDATE BRUP_REL
   SET RPRS_PET_YN = 'N'
     , MDFR_ID     = #{actorId}
     , MDFCN_DT    = NOW()
 WHERE MBR_SN = #{mbrSn}
   AND RPRS_PET_YN = 'Y'

/* 대표 반려동물 지정 */
UPDATE BRUP_REL
   SET RPRS_PET_YN = 'Y'
     , MDFR_ID     = #{actorId}
     , MDFCN_DT    = NOW()
 WHERE MBR_SN = #{mbrSn}
   AND PET_SN = #{petSn}
   AND USE_YN = 'Y'
